class Example extends Phaser.Scene {
  create () {
    const player = this.add.rectangle(400, 300, 23, 23, 0xff4444);
    const cursors = this.input.keyboard.createCursorKeys();
    this.events.on('update', () => {
      if (cursors.left.isDown)  player.x -= 7;
      if (cursors.right.isDown) player.x += 7;
      if (cursors.up.isDown)    player.y -= 7;
      if (cursors.down.isDown)  player.y += 7;
      player.x = Phaser.Math.Clamp(player.x, 11.5, 788.5);
      player.y = Phaser.Math.Clamp(player.y, 11.5, 588.5);
    });
  }
}
new Phaser.Game({ type: Phaser.AUTO, width: 800, height: 600, backgroundColor: '#1a1a2e', scene: Example });
```

